'use strict';
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='living-room-cinema-draft-v1';
let state={requests:[],added:[],rsvps:[],subscribers:[],event:null};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&['requests','added','rsvps','subscribers'].every(k=>Array.isArray(saved[k])))state=saved;}catch{}
state.votes = state.votes && typeof state.votes === 'object' ? state.votes : {};
const allMovies=()=>[...window.MOVIES,...state.added];
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function save(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;return true}catch{toast('This browser could not save your draft. Your form is still here.');return false}}
function voteCount(id){return state.votes[id]===true?1:0}
function ratings(m){return `<div class="ratings"><a href="${escapeHTML(m.imdb?.url||'https://www.imdb.com/')}" target="_blank" rel="noopener noreferrer" aria-label="IMDb rating for ${escapeHTML(m.title)}"><span class="imdb-label">IMDb</span> ${m.imdb?m.imdb.value.toFixed(1)+'/10':'Not rated'}</a><a href="${escapeHTML(m.rt?.url||'https://www.rottentomatoes.com/')}" target="_blank" rel="noopener noreferrer" aria-label="Rotten Tomatoes critics score for ${escapeHTML(m.title)}"><span aria-hidden="true">🍅</span> ${m.rt?m.rt.value+'%':'Not rated'}</a></div>`}
function toggleVote(id){if(!allMovies().some(m=>m.id===id))return;const voted=!state.votes[id];if(save({...state,votes:{...state.votes,[id]:voted}})){render();document.querySelector(`[data-vote="${id}"]`)?.focus();toast(voted?'One little vote for movie night. Saved locally!':'Vote removed. The plot thickens.')}}
function render(){const movies=allMovies();$('#count').textContent=movies.length;$('#movies').innerHTML=movies.map(m=>`<article class="movie"><div class="poster"><img src="${escapeHTML(m.poster)}" alt="${escapeHTML(m.title)} movie poster" loading="lazy" width="300" height="450"><span class="year">${escapeHTML(m.year)}</span></div><h3>${escapeHTML(m.title)}</h3><p class="genres">${m.genres.map(escapeHTML).join(' · ')}</p>${ratings(m)}<p class="description">${escapeHTML(m.description)}</p><div class="vote-row"><button class="vote-button ${voteCount(m.id)?'voted':''}" data-vote="${escapeHTML(m.id)}" aria-pressed="${!!voteCount(m.id)}" aria-label="${voteCount(m.id)?'Remove vote for':'Vote for'} ${escapeHTML(m.title)}">${voteCount(m.id)?'✓ Voted':'+ Vote'}</button><span class="vote-count"><span class="tally" aria-hidden="true">${voteCount(m.id)?'Ⅰ':'—'}</span> ${voteCount(m.id)} ${voteCount(m.id)===1?'vote':'votes'}</span></div></article>`).join('');$('#movies').querySelectorAll('img').forEach(img=>img.onerror=()=>{img.alt='Poster unavailable: '+img.alt;img.style.objectFit='contain'});document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>toggleVote(b.dataset.vote));if(state.event){const m=allMovies().find(m=>m.id===state.event.movie);if(m){$('#screening-title').textContent=m.title;$('#screening-info').textContent=eventLabel();$('#rsvp-open').disabled=false;$('#rsvp-open').textContent='Save my seat';}}}
function eventLabel(){if(!state.event)return '';return new Date(state.event.date).toLocaleString(undefined,{weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'})+' · '+state.event.location;}
render();
const dialog=$('#dialog');
function openDialog(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal()}
$('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const field=(name,label,type='text',value='',extra='')=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" required maxlength="200" ${extra}>`;
function suggest(){openDialog(`<p class="eyebrow">PUT SOMETHING ON OUR RADAR</p><h2>What should we watch?</h2><p>Just a title is enough. We’ll take care of the poster and the rest.</p><form id="suggest-form">${field('title','Movie title')}${field('name','Your name (optional)','text').replace(' required','')}<button class="button">Send suggestion</button><p class="muted">This trial request stays in your browser’s host view.</p></form>`);$('#suggest-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title)return;const req={id:crypto.randomUUID(),title,name:f.get('name').trim()||'A movie lover'};if(save({...state,requests:[...state.requests,req]})){dialog.close();toast('Suggestion saved. You can review it in Host view.')}}}
$('#suggest-open').onclick=suggest;
function host(){openDialog(`<p class="eyebrow">HOST VIEW · LOCAL DEMO</p><h2>Set the scene.</h2><p class="muted">Try the host controls here. A private host login will be added before launch.</p><form id="event-form"><p class="muted">Films are listed by votes, highest first. Pick a winner and set the date.</p><label for="film-pick">This week’s film</label><select id="film-pick" name="movie">${[...allMovies()].sort((a,b)=>voteCount(b.id)-voteCount(a.id)).map(m=>`<option value="${escapeHTML(m.id)}" ${state.event?.movie===m.id?'selected':''}>${escapeHTML(m.title)} (${m.year}) · ${voteCount(m.id)} votes</option>`).join('')}</select>${field('date','Date and time','datetime-local',state.event?.date||'')}${field('location','Where we’re watching','text',state.event?.location||'Our living room')}<button class="button">Save screening</button></form><hr><h2>Movie suggestions</h2><div id="requests">${state.requests.length?state.requests.map(r=>`<div class="request"><strong>${escapeHTML(r.title)}</strong><p class="muted">Suggested by ${escapeHTML(r.name)}</p><button class="button small" data-review="${escapeHTML(r.id)}">Review & add</button></div>`).join(''):'<p class="muted">No requests yet. Try suggesting a film.</p>'}</div><hr><h2>The guest list</h2><p>${state.rsvps.filter(r=>r.event===state.event?.id).length} RSVPs for the current screening · ${state.subscribers.length} movie-mail signups</p>${state.rsvps.filter(r=>r.event===state.event?.id).map(r=>`<p class="muted">${escapeHTML(r.name)} · ${escapeHTML(r.email)}</p>`).join('')}<button class="button" id="email-preview" ${!state.event?'disabled':''}>Preview weekly email</button><p class="muted">Email preview only; nothing is sent.</p>`);$('#event-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const date=f.get('date');if(new Date(date)<=new Date()){toast('Choose a future date for your screening.');return}const same=state.event?.movie===f.get('movie')&&state.event?.date===date;const event={id:same?state.event.id:crypto.randomUUID(),movie:f.get('movie'),date,location:f.get('location').trim()};if(!event.location)return;if(save({...state,event})){render();host();toast('Screening saved to this local draft.')}};document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));$('#email-preview').onclick=emailPreview;}
$('#host-open').onclick=host;
function review(id){const r=state.requests.find(r=>r.id===id);if(!r)return;openDialog(`<p class="eyebrow">FROM THE SUGGESTION BOX</p><h2>Add to the watchlist</h2><form id="approve-form">${field('title','Movie title','text',r.title)}${field('year','Release year','number','','min="1888" max="2100"')}${field('genres','Genres (separate with commas)')}${field('poster','Poster image URL','url','','placeholder="https://…"')}<label for="description">Short description</label><textarea id="description" name="description" required maxlength="500"></textarea><button class="button">Approve & add film</button></form>`);$('#approve-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let url;try{url=new URL(f.get('poster'));if(url.protocol!=='https:')throw 0}catch{toast('Please use an https:// poster image URL.');return}const m={id:crypto.randomUUID(),title:f.get('title').trim(),year:Number(f.get('year')),genres:f.get('genres').split(',').map(s=>s.trim()).filter(Boolean),poster:url.href,description:f.get('description').trim()};if(!m.title||!m.genres.length||!m.description)return;if(save({...state,added:[...state.added,m],requests:state.requests.filter(x=>x.id!==id)})){render();host();toast('Film added to your local watchlist.')}}}
$('#rsvp-open').onclick=()=>{if(!state.event)return;const m=allMovies().find(m=>m.id===state.event.movie);openDialog(`<p class="eyebrow">THERE’S A PLACE FOR YOU</p><h2>Save your seat.</h2><p>${escapeHTML(m.title)}<br>${escapeHTML(eventLabel())}</p><form id="rsvp-form">${field('name','Your name')}${field('email','Email address','email')}<button class="button">I’ll be there</button><p class="muted">Trial RSVP only, saved in this browser.</p></form>`);$('#rsvp-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),email=f.get('email').trim().toLowerCase();if(!name)return;const r={name,email,event:state.event.id};if(save({...state,rsvps:[...state.rsvps.filter(x=>!(x.email===email&&x.event===r.event)),r]})){dialog.close();toast('Your trial RSVP is saved. See it in Host view.')}}};
$('#subscribe-form').onsubmit=e=>{e.preventDefault();const email=$('#subscribe-email').value.trim().toLowerCase();if(save({...state,subscribers:[...new Set([...state.subscribers,email])]})){e.target.reset();toast('Signup saved locally. Weekly emails aren’t connected yet.')}};
function emailPreview(){const m=allMovies().find(m=>m.id===state.event.movie);const text=`Subject: This week at The Living Room Cinema: ${m.title}\n\nHello, movie people!\n\nThis week we’re watching ${m.title} (${m.year}).\n\n${m.description}\n\n${eventLabel()}\n\nSave your seat on The Living Room Cinema website.\n[Your public RSVP link will go here before sending.]\n\nSee you when the lights go down!\n\nThe Living Room Cinema\n[An unsubscribe link will be included before sending.]`;openDialog(`<p class="eyebrow">WEEKLY INVITATION · PREVIEW</p><h2>A little movie mail.</h2><div class="email-preview">${escapeHTML(text)}</div><p class="muted">No emails have been sent. This will use your public website link when email delivery is connected.</p>`)}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_movie_watchlist',description:'Read the local cinema watchlist and selected screening.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({movies:allMovies().map(({title,year,genres})=>({title,year,genres})),screening:state.event})})).catch(()=>{})}catch{}}
